/**
 * Brand marks (0.9, design language §4): the Teleply logo only from the final asset (brand/mark.svg, the path the web's
 * account page draws), black on light and white on dark; Codex, Claude and DeepSeek keep their own marks and colours
 * as the web sidebar draws them (static/sidebar-ui.js MARK; Claude and DeepSeek paths from Simple Icons, CC0).
 */
object TeleplyBrand {
    /** The Teleply mark: a screen with a prompt beside a phone; 1000 × 822, filled with the tint. */
    val Mark: ImageVector by lazy {
        ImageVector.Builder(name = "teleply", defaultWidth = 30.dp, defaultHeight = 24.66.dp, viewportWidth = 1000f, viewportHeight = 822f).apply {
            addPath(pathData = addPathNodes(MARK), fill = SolidColor(Color.Black))
        }.build()
    }
    /** Codex: a code symbol, stroked like the web's (1.7, round). */
    val Codex: ImageVector by lazy {
        ImageVector.Builder(name = "codex", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f).apply {
            addPath(pathData = addPathNodes("m8 6-6 6 6 6m8-12 6 6-6 6m-3-14-2 16"), fill = null, stroke = SolidColor(Color.Black),
                strokeLineWidth = 1.7f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)
        }.build()
    }
    val Claude: ImageVector by lazy { filled("claude", CLAUDE) }
    val DeepSeek: ImageVector by lazy { filled("deepseek", DEEPSEEK) }

    /** Brand colours (web: .mark.claude #d97757, .mark.deepseek #4d6bfe; Codex ink, white text colour on dark). */
    val ClaudeColor = Color(0xFFD97757)
    val DeepSeekColor = Color(0xFF4D6BFE)

    private fun filled(name: String, d: String) =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f).apply {
            addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
        }.build()

